      const party = pn(t.party, t.start);
      const base = { ch: t.type === 'sen' ? 'S' : 'H', st: t.state, real: !!STATEHOOD[t.state] && new Date(a).getUTCFullYear() >= STATEHOOD[t.state], a0: a };   // real = a seat for a state, not a territorial delegate
