      const pa = (t.party_affiliations || []).filter(x => x.party && x.start && x.end);
      if (pa.length > 1) pa.forEach(x => { const xa = Math.max(a, Date.parse(x.start)), xb = Math.min(b, Date.parse(x.end)); if (xb > xa) rec.terms.push(Object.assign({}, base, { party: pn(x.party, x.start), a: xa, b: xb })); });
